func (v *Arguments) tfield(name string) (any, bool) {
	switch name {
	case "PosOnlyArgs":
		return func() any {
			if v.PosOnlyArgs == nil {
				return nil
			}
			kids := make([]any, len(v.PosOnlyArgs))
			for i, x := range v.PosOnlyArgs {
				kids[i] = tptr(x)
			}
			return tlistOf(kids)
		}(), true
	case "Args":
		return func() any {
			if v.Args == nil {
				return nil
			}
			kids := make([]any, len(v.Args))
			for i, x := range v.Args {
				kids[i] = tptr(x)
			}
			return tlistOf(kids)
		}(), true
	case "VarArg":
		return tptr(v.VarArg), true
	case "KwOnlyArgs":
		return func() any {
			if v.KwOnlyArgs == nil {
				return nil
			}
			kids := make([]any, len(v.KwOnlyArgs))
			for i, x := range v.KwOnlyArgs {
				kids[i] = tptr(x)
			}
			return tlistOf(kids)
		}(), true
	case "KwDefaults":
		return func() any {
			if v.KwDefaults == nil {
				return nil
			}
			kids := make([]any, len(v.KwDefaults))
			for i, x := range v.KwDefaults {
				kids[i] = any(x)
			}
			return tlistOf(kids)
		}(), true
	case "KwArg":
		return tptr(v.KwArg), true
	case "Defaults":
		return func() any {
			if v.Defaults == nil {
				return nil
			}
			kids := make([]any, len(v.Defaults))
			for i, x := range v.Defaults {
				kids[i] = any(x)
			}
			return tlistOf(kids)
		}(), true
	}
	return nil, false
}

