func tmk_Alias(c *tctx, final bool, f0 any, f1 any) any {
	a := c.p.ext.(*tslabs)
	v := astNew(&a.tAlias)
	v.Name = astString(f0)
	v.AsName = astString(f1)
	if final {
		v.Span = Span{c.start, c.end}
		return v
	}
	first, start, end := true, 0, 0
	spanOf(f0, &first, &start, &end)
	spanOf(f1, &first, &start, &end)
	return c.made(v, first, start, end)
}

